// Fail2banHostInputPreview defines model for Fail2banHostInputPreview.
type Fail2banHostInputPreview struct {
	At        int64                            `json:"at"`
	Available bool                             `json:"available"`
	Backend   Fail2banHostInputPreviewBackend  `json:"backend"`
	CanApply  Fail2banHostInputPreviewCanApply `json:"can_apply"`

	// CanPrepare 须本机登记、保护来源及完整官方 jail 封禁快照均已核对，才生成当前集合的准备材料；不授予封禁执行权
	CanPrepare     bool                         `json:"can_prepare"`
	GeneratedRules int                          `json:"generated_rules"`
	Hook           Fail2banHostInputPreviewHook `json:"hook"`

	// Kernel 固定 inet 目标表在同一内核代次的有界快照；完整原始表达式仅参与摘要，不返回规则正文，不证明所有权。
	Kernel  FirewallKernelView `json:"kernel"`
	Manager string             `json:"manager"`

	// ManagerObservedAt 管理器缓存采样时间，区别本次独立目标表采样；尚未取得为 0
	ManagerObservedAt int64                            `json:"manager_observed_at"`
	Priority          Fail2banHostInputPreviewPriority `json:"priority"`
	ProgramHash       string                           `json:"program_hash"`

	// ProtectedSources 完整条件满足后，本次采样的本地单地址、固定保留网段及 root 批准的管理/代理来源的规范化并集
	ProtectedSources []string                        `json:"protected_sources"`
	Protection       Fail2banHostInputProtectionView `json:"protection"`
	Reason           string                          `json:"reason"`

	// Registration 本机 root 独立登记核对结果；直接 nftables 核对空表及内核快照，firewalld 核对原登记或已确认 policy 的完整 runtime/permanent 设置与活动绑定；UFW 核对宿主机持久占用、原本机授权与回执及空标记命名空间，iptables 核对显式后端、本机占用、原回执以及空命名空间或已确认的完整受管代际；授权登记不安装规则；不表示获得业务策略写入授权或外部可达。
	Registration FirewallRegistrationView     `json:"registration"`
	Runtime      Fail2banHostInputRuntimeView `json:"runtime"`
	Scope        string                       `json:"scope"`
	Sources      Fail2banHostInputSourcesView `json:"sources"`

	// Sync 本机 root 明确批准的持续会话，只读状态不授予执行权；current 仅证明最近完整官方采样与所属内核对象一致，采样超过 60 秒则等待重新核对。
	Sync             Fail2banHostInputSyncView     `json:"sync"`
	Table            Fail2banHostInputPreviewTable `json:"table"`
	TransactionBytes int                           `json:"transaction_bytes"`
	TransactionHash  string                        `json:"transaction_hash"`
}

